javascript.solution:
const input = require("fs").readFileSync(0, "utf8");

const INT_MIN = -(2 ** 31);
const INT_MAX = 2 ** 31 - 1;

function reverseInteger(x) {
  let result = 0;
  while (x !== 0) {
    // x % 10 keeps the sign of x, so a negative x builds a negative result.
    result = result * 10 + (x % 10);
    x = Math.trunc(x / 10);
  }
  if (result < INT_MIN || result > INT_MAX) {
    return 0;
  }
  return result;
}

const x = Number(input.trim());
console.log(reverseInteger(x));

